(1) API role:
CREATE ROLE api_service;
GRANT CONNECT ON DATABASE arcane TO api_service;
GRANT USAGE ON SCHEMA public TO api_service;
GRANT SELECT, INSERT, UPDATE ON apprentices TO api_service;
GRANT SELECT, INSERT ON quest_completions TO api_service;
-- No DELETE — soft deletes only; no access to payments

(2) Reporting role:
CREATE ROLE reporting_service;
GRANT CONNECT ON DATABASE arcane TO reporting_service;
GRANT USAGE ON SCHEMA public TO reporting_service;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO reporting_service;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT TO reporting_service;
-- Read-only; no INSERT/UPDATE/DELETE

(3) Migration runner:
CREATE ROLE migration_runner CREATEDB;
GRANT CONNECT ON DATABASE arcane TO migration_runner;
GRANT ALL ON SCHEMA public TO migration_runner;
GRANT ALL ON ALL TABLES IN SCHEMA public TO migration_runner;
-- Run only from CI pipeline, never from live application
-- Consider time-boxing: revoke after migration completes, re-grant before next
